insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('appliedai', 'beginner', 'module', 'm01-what-copilots-and-retrieval-do', 1, 'Which language model does the evaluation engine call when it scores a copilot?', '["A small model that it runs locally to judge whether each cited answer is true before the claims are counted.", "One that embeds every passage, so that BM25 and TF-IDF can compare meanings as well as words.", "None: its imports are lib/stats, the percentile conventions and the machine learning engine, and its source makes no network call.", "Only the model behind system B, which it asks to rerank the TF-IDF list and then to grade each rewritten answer before scoring."]'::jsonb, 2, 'The engine runs no language model: it writes no answer, embeds no text, reranks nothing and asks no model to judge an answer, and its imports are lib/stats, lib/conventions/percentile.js and the machine learning engine. There is no dense retrieval to compare meanings, and system B is a fixed TF-IDF retriever with hand-written answers, so there is nothing to rerank.'),
  ('appliedai', 'beginner', 'module', 'm01-what-copilots-and-retrieval-do', 2, 'Q14 asks "Is Ekene-5 producing water?" and BM25 finds none of its 3 relevant passages in the top 5. What causes the miss?', '["The passages say \"no water\" and \"water free\", and the engine matches tokens alone, with no synonym list and no stemming.", "BM25 drops the word water because it appears in too many passages, so the query is scored on producing alone.", "System A ran with the stop list on, which removed every word in the query that the passages share.", "Q24 was excluded from the means, and its judgments were merged into Q14''s by the pooling step."]'::jsonb, 0, 'Q14 is a planted lexical trap: the answering passages say "no water" and "water free" while the query says "producing water", and the engine retrieves by words alone. A common word keeps a positive BM25 idf, so it is never dropped. System A ran with the stop list off. Q24''s exclusion from the means has nothing to do with Q14''s ranking.'),
  ('appliedai', 'beginner', 'module', 'm01-what-copilots-and-retrieval-do', 3, 'EKD-058 is an exact copy of EKD-046, a spill note filed twice. What decides which of the two ranks first?', '["Each passage''s date, so that the note filed earlier is always placed first in the list.", "Passage type, because an hse_note outranks every other type when two passages share a score.", "Whichever the fixture lists first, which makes the result depend on how the files were written.", "The tie rule: equal scores tie and the id ascending puts EKD-046 first."]'::jsonb, 3, 'Every method scores the two copies alike, so their order comes from the ranking rule: scores that agree to 12 significant digits tie, and ties go to the document id ascending. The engine indexes the text alone, so a passage''s date and type play no part, and a stated rule replaces input order so the same inputs always give the same list.'),
  ('appliedai', 'beginner', 'module', 'm01-what-copilots-and-retrieval-do', 4, 'On the four-grade scale used for the Ekene judgments, what does grade 1 mean?', '["Answers the query, which is the highest grade a judged passage can receive from the assessor.", "Related, and at the default threshold it still counts as relevant.", "Judged not relevant, so it is left out of every metric in the same way as an unjudged passage.", "Relevant, the middle grade, which the course counts only when the threshold is raised to 2."]'::jsonb, 1, 'The fixture grades are 3 answers the query, 2 relevant, 1 related and 0 judged not relevant. The course calls a passage relevant at or above a stated threshold, grade 1 by default, so a related passage counts. Grade 3 is the top grade and grade 0 is the judged not-relevant grade, and at a threshold of 2 grade 1 would stop counting.'),
  ('appliedai', 'beginner', 'module', 'm01-what-copilots-and-retrieval-do', 5, 'A new retriever, one the pool was not built from, puts a passage nobody judged into its top 5 for a query. How is that passage graded?', '["As grade 0, because unjudged passages count as grade 0.", "As grade 1, since a passage a retriever found is assumed to be at least related to the query.", "It is removed from the ranked list first, and every passage below it moves up one rank.", "The engine refuses the call and names the passage, since every retrieved passage needs a grade."]'::jsonb, 0, 'The stated rule is that unjudged passages count as grade 0. No grade is assumed for a retrieved passage, the ranking is never edited to drop it, and the call is not refused: an unjudged passage is an ordinary part of a ranked list.'),
  ('appliedai', 'beginner', 'module', 'm01-what-copilots-and-retrieval-do', 6, 'How was the set of judged (query, passage) pairs for the Ekene queries built?', '["By judging every one of the 60 passages against all 24 queries, so no pair was left unjudged.", "From system A''s top 5 alone, since BM25 is the retriever the course treats as the reference.", "By sampling passages with a seeded random draw so that each query received a similar count.", "By pooling: every passage in either system''s top 5 was judged, plus passages the assessor added."]'::jsonb, 3, 'The judged set was pooled: every passage in the top 5 of either system, BM25 and TF-IDF at default settings, plus passages the assessor added, 183 pairs in all. Judging every pair would give far more than 183, both systems fed the pool, and no random draw chose the judged passages.'),
  ('appliedai', 'beginner', 'module', 'm01-what-copilots-and-retrieval-do', 7, 'Which settings did system A use to retrieve its top 5?', '["TF-IDF on raw counts with the smoothed idf, and the stop list on for every query.", "BM25 with k1 1.2 and b 0.75, the stop list off.", "BM25 with k1 2 and b 1.", "Its retriever was a dense embedding search followed by BM25 on the passages it kept."]'::jsonb, 1, 'The fixture states system A as bm25 k 5 k1 1.2 b 0.75, stop list off, and system B as tfidf k 5, stop list off. TF-IDF is system B''s method and neither system switched the stop list on. k1 2 and b 1 are settings the course explores on Q13, and system A kept the defaults; the engine has no embedding search.'),
  ('appliedai', 'beginner', 'module', 'm01-what-copilots-and-retrieval-do', 8, 'Why can no question key or capstone field in this course rest on a language model''s output?', '["The fixture answers were written by a model, so scoring a second model''s output would count it twice.", "Language models refuse to cite passages, so there would be nothing for the claim check to read.", "Model output changes between runs and versions, so a key resting on it would have no fixed right answer.", "The engine has a model built in, and letting a second one grade it would create a conflict of scores."]'::jsonb, 2, 'A graded answer needs exactly one right value on any machine and any day. Output from a language model changes from run to run and from one model version to the next, so a model''s output is an input to be scored and never a key. The fixture answers are hand-written and no model wrote them, and the engine contains no model.'),
  ('appliedai', 'beginner', 'module', 'm01-what-copilots-and-retrieval-do', 9, 'What does the engine return when it refuses an input it cannot use?', '["A result object with every value set to null and no sentence explaining which input caused it.", "It throws an exception that stops the panel and asks the user to reload the page before trying again.", "An object with `error` and `field`, where the message starts with the field it names.", "A result with a `note`, since a refusal and a note are the same thing."]'::jsonb, 2, 'Every function returns either a result or an object with `error` and `field`, where `field` names the input it refused and the message starts with that name. A refusal is never a silent null. A note is different: it comes with a result from a call that ran, and a refusal means the call did not run.'),
  ('appliedai', 'beginner', 'module', 'm01-what-copilots-and-retrieval-do', 10, 'EKD-001 is passed twice in one documents list. Which field does the refusal name?', '["documents[0].id, the first copy of the id, which the engine treats as the offending entry in the list", "query, which is checked first", "documents, the list as a whole", "documents[1].id, the position of the repeat"]'::jsonb, 3, 'The engine''s own words are "documents[1].id repeats EKD-001 (documents[0])": the field names the position of the repeat, counted from 0, and the bracket points back at the first copy. It names the second entry, the one that repeats, and the message is about the documents list entry, so neither the query nor the whole list is named.'),
  ('appliedai', 'beginner', 'module', 'm01-what-copilots-and-retrieval-do', 11, 'A call asks `retrieve` for a method this engine does not offer. What is the engine''s message?', '["method must be ''bm25'' or ''tfidf''", "the call is run with BM25 instead, and a note in the result says so", "method is unknown, and the passages are returned in the order they were given", "query must be a string"]'::jsonb, 0, 'The refusal names `method`, and the engine''s own words are "method must be ''bm25'' or ''tfidf''". The engine never substitutes a method or returns an unranked list in place of a refusal. "query must be a string" is the refusal for a query that is not text, a different input.'),
  ('appliedai', 'beginner', 'module', 'm01-what-copilots-and-retrieval-do', 12, 'The query helicopter is run by BM25 on the Ekene passages, and no passage contains the word. What comes back?', '["A refusal naming `query`, with the message \"query must be a string\", because the word is unknown to the corpus vocabulary", "It runs and returns the note \"no document contains a query term, so no document is ranked\"", "A ranking of all 60 passages at score 0, in id order", "The five shortest passages, since each scores the same when nothing matches"]'::jsonb, 1, 'A query whose words appear in no passage is not refused: the call runs and returns an empty ranking with the note "no document contains a query term, so no document is ranked". "query must be a string" is the refusal for a query that is not text. Only a score above 0 is ranked, so no passage is listed at score 0 and no passage is chosen by its length.'),
  ('appliedai', 'beginner', 'module', 'm01-what-copilots-and-retrieval-do', 13, 'System A''s answer to Q06 states a maximum oil column of 20.3 m, a figure that is in EKD-007 only. What does the course call that claim?', '["A supported claim, since the figure does appear somewhere in the Ekene corpus and can be found", "A correct abstention, since it cites a passage", "An identifier with no claim in it", "An unsupported claim, which this course calls a hallucination"]'::jsonb, 3, 'EKD-007 was neither retrieved nor cited, so the check could not find 20.3 in a cited, retrieved passage: that is an unsupported claim, which is what this course means by a hallucination, named with the engine''s reason. Support needs a cited and retrieved passage; appearing elsewhere in the corpus is no support. An abstention states no figure, and 20.3 stands apart from any word, so it is a claim and no identifier.'),
  ('appliedai', 'beginner', 'module', 'm01-what-copilots-and-retrieval-do', 14, 'In this course, what does the word "AI" name?', '["The system being evaluated, such as a copilot or a search box.", "BM25 and TF-IDF, the two ranking methods.", "Anything automated in the engine, including the tokeniser that splits every passage into words.", "The claim check and the tie rule, the steps that decide without a person looking."]'::jsonb, 0, 'The vocabulary rule is that "AI" names the system being evaluated. The engine runs no model, and every method is named by what it is: tokenising, TF-IDF, BM25, a ranking rule, a claim check. Calling a ranking method, the tokeniser, the claim check or the tie rule AI would name a method this engine runs, which the rule forbids.'),
  ('appliedai', 'beginner', 'module', 'm01-what-copilots-and-retrieval-do', 15, 'For Q02 "initial oil rate of Ekene-3", BM25 ranks the drilling report EKD-043 first at 5.129851. Why does it outrank EKD-003, the passage that answers the query?', '["It has the highest judged grade for Q02, and BM25 reads the judgments while it scores the passages.", "It shares the words rate and of with the query, and BM25 matches words without any sense of meaning.", "It is the shortest passage in the corpus, and BM25 always puts the shortest match first on any query.", "Its score is a probability of 5.129851 against the 4.084216 given to EKD-003, so it is more likely."]'::jsonb, 1, 'EKD-043 is a drilling report about the rate of penetration and ranks first on the words rate and of. Its judged grade for Q02 is 0, and BM25 never reads judgments. It has 41 tokens, so it is not the shortest passage, and a BM25 score is a sum over matched words: a score is never a probability.'),
  ('appliedai', 'beginner', 'module', 'm02-tokens', 1, 'How many tokens does the engine make of `Ekene-3 flowed 1.25 MMscf/d; Top WELL at 1548 m TVD.` with the stop list off?', '["10, since the stop list is applied before the text is split into its tokens", "13", "9, because \"1.25\" and \"MMscf/d\" each stay whole as a single token", "11"]'::jsonb, 1, 'The engine splits on every run of characters outside [a-z0-9]: ekene 3 flowed 1 25 mmscf d top well at 1548 m tvd, 13 tokens. The decimal point and the slash both separate, and so does the hyphen in Ekene-3. 10 is the count with the stop list on, which removes top, well and at, and the list is off by default.'),
  ('appliedai', 'beginner', 'module', 'm02-tokens', 2, 'What does the tokeniser make of the figure "2,096" in `Average reservoir pressure 2,096 psia on 2023-01-01.`?', '["One token, 2096", "The single token 2,096, because a comma between digits is read as part of a number", "One token, 2, since the engine drops any piece that starts with a zero after splitting", "Two tokens, 2 and 096"]'::jsonb, 3, 'A comma is outside [a-z0-9], so it separates: "2,096" becomes 2 and 096, and the leading zero stays because nothing but case is changed. The tokeniser keeps no comma inside a token and joins no digits across one, and an empty piece is the only piece it drops.'),
  ('appliedai', 'beginner', 'module', 'm02-tokens', 3, 'What tokens does `Café Überprüfung naïve` give?', '["caf berpr fung na ve", "cafe uberprufung naive, with each accent folded to its plain letter", "café überprüfung naïve, lowercased with the accents left in place", "no tokens at all"]'::jsonb, 0, 'Only ASCII A to Z are lowercased, and every character outside [a-z0-9] separates, so each accented letter splits the word: caf berpr fung na ve, 5 tokens. The engine folds no accents and keeps no accented letter in a token, and the text is accepted, since the only text refusals are for a text that is not a string or one above 20000 characters.'),
  ('appliedai', 'beginner', 'module', 'm02-tokens', 4, 'How does the tokeniser split `Core plug EK1-P: permeability 420 md.`?', '["core plug ek 1 p permeability 420 md", "core plug ek1-p permeability 420 md", "core plug ek1 p permeability 420 md, with ek1 kept as one token", "just core plug permeability md"]'::jsonb, 2, 'Letters and digits that sit together stay together, so EK1 is the single token ek1, and the hyphen splits off p: 7 tokens in all. The rule cuts only at characters outside [a-z0-9], so a letter-digit boundary is no cut, a hyphen always separates, and single characters and numbers are kept.'),
  ('appliedai', 'beginner', 'module', 'm02-tokens', 5, 'Which tokens does `Bit graded 2-3-WT at 1760 m MD.` give?', '["bit graded 2-3-wt at 1760 m md", "bit graded 23wt at 1760 md", "only bit graded wt 1760 md, dropping the single characters 2, 3 and m as too short", "bit graded 2 3 wt at 1760 m md, 9 tokens"]'::jsonb, 3, 'Each hyphen separates, so the grade 2-3-WT becomes 2, 3 and wt, and the text gives 9 tokens. The rule never keeps a hyphen inside a token, never joins pieces across a separator, and keeps single-character tokens such as 2, 3 and m: a common alternative that keeps only two characters or more is the one this engine did not take.'),
  ('appliedai', 'beginner', 'module', 'm02-tokens', 6, 'A report says "producing" and a query says "produced". How many tokens do the two words share?', '["One, since both are cut back to the root produc", "None, since no stemming is done and the words stay different tokens", "Both, since lowercasing maps them to one token", "One, through a synonym list that pairs the forms"]'::jsonb, 1, 'The rule ends "no stemming": nothing is cut back to a root, so "producing" and "produced" are different tokens and a query for one does not match the other. Lowercasing changes only A to Z, and the engine has no synonym list whatever the stop list setting.'),
  ('appliedai', 'beginner', 'module', 'm02-tokens', 7, 'Why does the engine leave scikit-learn''s stop list off by default?', '["It removes words with oilfield meaning, among them well, top, bottom, fire and system.", "It holds too few words to matter, so it changes no token count on the Ekene passages.", "Using it slows every call past the engine''s limits, so each call is refused whenever it is on.", "Its licence forbids use in a commercial engine, so it is shipped only for reading."]'::jsonb, 0, 'The engine''s stated reason is that the list removes well, top, bottom, fire and system, words that carry meaning in oilfield text. The list holds 318 words and cuts the corpus vocabulary from 574 to 505 tokens, so it matters. Switching it on is accepted, and the list is scikit-learn''s, under BSD-3-Clause, exported by the engine.'),
  ('appliedai', 'beginner', 'module', 'm02-tokens', 8, 'With the stop list on, a geologist types the query "the well top" into BM25. What comes back?', '["A refusal naming `query`, since a query of stop words is not a string", "A ranking on the word well alone, as the and top are the only words removed", "An empty ranking with the note \"the query has no token after the stop list, so no document is ranked\"", "Every passage at the same score, in id order, since nothing in the query can be weighed"]'::jsonb, 2, 'the, well and top are all on the stop list, so the query loses every token and the call returns with the note "the query has no token after the stop list, so no document is ranked". That is a note on a result that ran; the query is still a string, well is removed as well as the and top, and only a score above 0 ranks, so nothing is listed.'),
  ('appliedai', 'beginner', 'module', 'm02-tokens', 9, 'Q14 is "Is Ekene-5 producing water?". What changes when the stop list is switched on?', '["Nothing, since every word in Q14 is a content word that the list leaves alone", "water and producing are removed, leaving only ekene and 5 to be matched", "ekene and 5 are removed, since the list drops every name and every number", "The word is drops out, and \"no\", the word the answering passages use, is a stop word too"]'::jsonb, 3, 'With the list off Q14 keeps is, ekene, 5, producing, water; with it on it keeps ekene, 5, producing, water, so is goes. The word that answers it in the passages, "no", is itself a stop word, so with the list on no passage could match it. water and producing survive, and the list removes common words, never names or numbers as such.'),
  ('appliedai', 'beginner', 'module', 'm02-tokens', 10, 'EKD-001 has 56 tokens with the stop list off. What is its length for BM25 with the list on?', '["56, since a passage''s length is fixed when it is read and the stop list touches only the query", "33, since the length is the token count after the stop list", "0, since BM25 drops length once the list is on", "38.316667, the corpus mean length"]'::jsonb, 1, 'A passage''s length for BM25 is its token count after the stop list, so EKD-001 is 56 with the list off and 33 with it on. When the list is on it applies to the passages, the query and every length at once. BM25 still uses those lengths, so none of them drops to 0. 38.316667 is the corpus mean length with the list off, avgdl, and each passage keeps its own length.'),
  ('appliedai', 'beginner', 'module', 'm02-tokens', 11, 'What do the corpus vocabulary and the mean passage length become with the stop list on?', '["505 tokens and 27.483333, against 574 and 38.316667 with it off", "574 tokens and 38.316667 again, since the list changes queries and leaves passages alone", "318 tokens and 27.483333, since the vocabulary shrinks to the size of the stop list itself", "505 tokens and 38.316667"]'::jsonb, 0, 'The engine counts 505 tokens of vocabulary and a mean length of 27.483333 with the list on, against 574 and 38.316667 with it off. The list applies to passages as well as queries, so the lengths fall with it. 318 is the number of words on the stop list, which is a different quantity.'),
  ('appliedai', 'beginner', 'module', 'm02-tokens', 12, 'A call passes the word "yes" as the stop list switch. What does the engine return?', '["The list switched on, reading the word as yes", "Tokens with the list off and a note saying the switch was not understood", "A refusal naming `stopWords`: \"stopWords must be true or false\"", "A refusal naming `text`"]'::jsonb, 2, 'The switch takes true or false and nothing else. The engine''s own words are "stopWords must be true or false", and the refusal names `stopWords`. It never guesses a meaning for a word, never runs with a note in place of the refusal, and names the switch itself as the field.'),
  ('appliedai', 'beginner', 'module', 'm02-tokens', 13, 'A passage of 20001 characters is handed to `tokenize`. What is the engine''s message?', '["the passage is cut at 20000 characters and the tokens of the kept part are returned", "documents has 5001 entries, above the 5000 this engine accepts", "text must be a string of 20000 characters exactly, padded if shorter", "text has 20001 characters, above the 20000 this engine accepts"]'::jsonb, 3, 'The most characters in one text is 20000, and one above is refused naming `text` in the engine''s words "text has 20001 characters, above the 20000 this engine accepts". The engine never truncates silently. "documents has 5001 entries, above the 5000 this engine accepts" is the refusal for too many documents, a different limit, and a shorter text is accepted as it is.'),
  ('appliedai', 'beginner', 'module', 'm02-tokens', 14, 'How does the tokeniser treat `oil_rate and water/cut`, with the stop list off and then on?', '["oil_rate and water/cut, 3 tokens, since the underscore and the slash join words", "oil rate and water cut, 5 tokens; with the list on, and is removed", "oil rate water cut, 4 tokens either way", "oilrate and watercut, 3 tokens, with each joiner deleted and the halves merged"]'::jsonb, 1, 'An underscore and a slash are outside [a-z0-9], so both separate: oil rate and water cut, 5 tokens. With the list on, and is removed, leaving oil rate water cut. With the list off every token is kept, and a separator never merges the pieces on either side.'),
  ('appliedai', 'beginner', 'module', 'm02-tokens', 15, 'The hand set passage d3 reads "Oil and water rates were tested; the oil rate was 150 bopd." What are its counts of oil and of rate?', '["oil 2 and rate 1, with rates a different token", "Two of each, since rates is counted with rate as the same word", "oil 1 and rate 1, since a word that appears twice in one passage is counted once", "oil 2 and rate 0, as the stop list removes rate from every passage"]'::jsonb, 0, 'd3 has 12 tokens: oil appears twice and rate once, and rates is its own token because nothing is stemmed. A repeated token counts every time it appears in a passage, and rate is no stop word; the list is off in any case.'),
  ('appliedai', 'beginner', 'module', 'm03-tf-idf', 1, 'On the hand set of five passages, oil is in d1 and d3. What is its TF-IDF idf?', '["0.875469, the Lucene form ln(1 + (N - df + 0.5) / (df + 0.5)) used by BM25", "2.098612, counting all 4 uses of oil", "0.707107, its weight in the query", "1.693147, from ln((1 + 5) / (1 + 2)) + 1"]'::jsonb, 3, 'The engine uses scikit-learn''s smoothed idf, ln((1 + N) / (1 + df)) + 1 with N 5 and df 2, which is 1.693147. 0.875469 is oil''s BM25 idf, a different formula. df counts passages, never occurrences, and 2.098612 is the idf of a word in 1 passage. 0.707107 is oil''s weight in the query vector, after scaling to unit length.'),
  ('appliedai', 'beginner', 'module', 'm03-tf-idf', 2, 'Which hand-set words share the TF-IDF idf 2.098612?', '["Only the rarest content words, since the engine gives stop words such as the a lower idf", "Every word in exactly one passage, such as injection, rates and the", "oil and rate, the two words of the query \"oil rate\"", "Each word that appears twice in one passage"]'::jsonb, 1, 'idf depends on df alone, so every word in exactly 1 of the 5 passages gets ln(6 / 2) + 1, 2.098612: 096, injection, rates and even the. The idf knows nothing about the word itself, and the stop list is off. oil and rate are each in 2 passages, so theirs is 1.693147, and a repeat inside one passage raises the count, never the df.'),
  ('appliedai', 'beginner', 'module', 'm03-tf-idf', 3, 'What TF-IDF idf would a word have if it appeared in every one of the five hand-set passages?', '["1, because the final + 1 keeps it above 0", "0, since a word found everywhere carries no information about which passage to pick", "A negative weight, as the logarithm of a fraction below 1 is negative", "2.098612, as for a rare word"]'::jsonb, 0, 'With df equal to N the fraction (1 + 5) / (1 + 5) is 1, its logarithm is 0, and the final + 1 leaves the idf at 1: a term in every passage would still have idf 1, never 0. The fraction never falls below 1 in this form, so the idf is never negative, and 2.098612 belongs to a word in one passage.'),
  ('appliedai', 'beginner', 'module', 'm03-tf-idf', 4, 'd1''s raw weights have norm 6.689301. What is oil''s weight in d1''s unit vector?', '["1.693147, the idf alone", "0.313727, as for every d1 word", "0.506225, from 2 x 1.693147 / 6.689301", "0.474658, the weight that scaling gives oil in d3, the longer passage"]'::jsonb, 2, 'oil has count 2 in d1 and idf 1.693147, and dividing that raw weight by the norm 6.689301 gives 0.506225. Every weight is divided, the heaviest included. 0.313727 is the weight of 1, 120 and fell, which appear once with the higher idf, and 0.474658 is oil''s weight in d3, whose norm is 7.134175.'),
  ('appliedai', 'beginner', 'module', 'm03-tf-idf', 5, 'Why does the engine scale every TF-IDF passage vector to length 1?', '["So that a long report that mentions a word once is rewarded for its extra length", "Because the idf alone cannot tell a rare word from a common one without it", "So a score depends on which words are shared and in what proportion, and the passage''s size drops out", "To turn each weight into the chance that the passage answers a query"]'::jsonb, 2, 'Dividing every weight by the norm keeps the vector pointing the same way and makes its length 1, so the passage''s mix of words remains and its size drops out: a long report is not rewarded for its length. The idf already separates rare from common words, and a unit weight is a weight, never a chance of answering.'),
  ('appliedai', 'beginner', 'module', 'm03-tf-idf', 6, 'The hand-set passage d5 is empty. What happens to it in TF-IDF?', '["It is a zero vector with norm 0, so it can never rank", "The engine refuses the whole call, naming `documents`, because one passage has no token in it", "It ranks last, with equal weights", "It takes the mean vector of the other four passages, so it can still be matched"]'::jsonb, 0, 'd5 has no tokens, every weight is 0 and its norm is 0; a vector of zeros cannot be scaled to length 1 and it can never rank. The empty-vocabulary refusal applies only when no passage in the call holds a token, and the engine invents no weights for an empty passage.'),
  ('appliedai', 'beginner', 'module', 'm03-tf-idf', 7, 'Ranked by TF-IDF cosine against the two-word query "oil rate", which figure does d1 reach, and from which products?', '["2.191027, the sum of d1''s two matched terms, oil and rate, each weighted by BM25", "1.000000, since both of the query''s words are in d1 and a full match scores 1", "0.506225, oil''s weight in d1 alone", "0.715911, from 0.707107 x 0.506225 twice, summed"]'::jsonb, 3, 'The query vector is oil 0.707107, rate 0.707107, and d1 weights each 0.506225, so the dot product is 0.715911. 2.191027 is d1''s BM25 score for the same query, a different quantity. A cosine reaches 1 only when the two vectors point the same way, and d1 holds other words, and every shared query word is scored.'),
  ('appliedai', 'beginner', 'module', 'm03-tf-idf', 8, '"oil rate" is ranked by cosine on the five hand-set passages at k 5. How many passages rank?', '["5, as k is 5 and a list is always filled to its cutoff", "2, d1 and d3", "4, since only the empty d5 is left out of the list", "3, d1, d2 and d3"]'::jsonb, 1, 'Only a score above 0 ranks. d2 and d4 share no term with the query and d5 is empty, so 2 of the 5 passages rank and the list is shorter than k. d2 shares no token with oil rate, water included, and the engine matches tokens only.'),
  ('appliedai', 'beginner', 'module', 'm03-tf-idf', 9, 'For Q04 "bubble point pressure of the Ekene oil", TF-IDF ranks EKD-018 first at 0.553949. Where is EKD-010, the passage judged to answer the query?', '["Second, at 0.328560", "First, since the judged grade 3 lifts it above every passage graded 2 in the list", "Fifth, at 0.251461, the lowest place in the top 5 at the cutoff", "Outside the top 5, as its words do not match the query"]'::jsonb, 0, 'The cosines run EKD-018 0.553949 (grade 2), EKD-010 0.328560 (grade 3), EKD-011, EKD-020 and EKD-057. A cosine measures shared words, so a passage can share more words with a query than the one that answers it, and the judgments play no part in the score. 0.251461 is EKD-057, graded 0.'),
  ('appliedai', 'beginner', 'module', 'm03-tf-idf', 10, 'In Q04''s query vector, which word carries the smallest weight, and why?', '["bubble, at 0.549668, as the longest word is weighted down to keep the vector at length 1", "ekene, at 0.204740, since a field name in its own field''s reports is always given the lowest weight", "oil, at 0.297012, as a title word", "the, at 0.188200, since it is common across the corpus"]'::jsonb, 3, 'The query is weighted like a passage, so common words get low idf: the carries 0.188200, the smallest weight. bubble, at 0.549668, is the heaviest, being rare. ekene is also low at 0.204740, above the and never forced to the bottom. Word length and titles play no part, since the engine indexes the text alone and weighs words by df.'),
  ('appliedai', 'beginner', 'module', 'm03-tf-idf', 11, 'Q24 "subsea tree replacement on Ekene-5" is ranked by TF-IDF. What happens to the words subsea and tree?', '["The engine refuses the query and names `query`, since two of its words are unknown", "They are dropped, because no passage contains them, and the cosine uses 5, ekene, on and replacement", "They get the largest idf, as a word in no passage is the rarest word of all", "They are stemmed to sub and tre and matched against every passage holding those"]'::jsonb, 1, 'Query terms outside the corpus vocabulary are dropped, so the cosine is computed on 5, ekene, on and replacement. Unknown words are no reason to refuse; if every query word were unknown the result would carry the note "no query term is in the corpus vocabulary, so no document is ranked". A word in no passage has no weight at all, and nothing is stemmed.'),
  ('appliedai', 'beginner', 'module', 'm03-tf-idf', 12, 'With sublinear tf on, what changes for Q13 "Ekene-6 water cut at the end of 2025"?', '["Every passage''s cosine is halved, since the idf is squared before the counts are applied", "The order flips, with EKD-030 moving above EKD-029 for the first time", "A count c becomes 1 + ln c, EKD-029 stays first at 0.395996, and EKD-030 rises to 0.382844", "Nothing, since sublinear tf applies to BM25 alone"]'::jsonb, 2, 'Sublinear tf replaces a count c by 1 + ln c before the idf, so a repeated word counts for less. On Q13 it moves the cosines and keeps the order: EKD-029 goes from 0.404014 to 0.395996 and EKD-030 from 0.355212 to 0.382844. The idf is unchanged, and sublinearTf is a TF-IDF switch.'),
  ('appliedai', 'beginner', 'module', 'm03-tf-idf', 13, 'Through rankTfidf, the hand-set query "oil oil rate" gives d1 a cosine of 0.679173. Why does it differ from 0.715911 for "oil rate"?', '["TF-IDF weights the query like a passage, so the repeat shifts the query vector to oil 0.894427, rate 0.447214", "The repeated word is refused, and the call is run again on rate alone as a fallback", "TF-IDF counts a repeated query word once, so the drop comes from d1''s own vector", "Repeating a word adds a penalty to every passage that holds it"]'::jsonb, 0, 'In TF-IDF the query is weighted the same way as a passage, raw counts times idf scaled to unit length, so "oil oil rate" gives oil 0.894427, rate 0.447214 and d1 moves to 0.679173. Nothing is refused and d1''s own vector is unchanged. Counting a repeat once is BM25''s rule, and there is no penalty term.'),
  ('appliedai', 'beginner', 'module', 'm03-tf-idf', 14, 'A TF-IDF call is given one passage, and it is empty. What does the engine return?', '["A result with a note, since an empty passage is ranked with a note and no refusal", "An empty ranking and a vocabulary of 0 terms, without any refusal or note", "documents must be a non-empty array of { id, text }", "A refusal: \"documents has no token in any text: the vocabulary is empty\""]'::jsonb, 3, 'A vocabulary needs at least one token somewhere; with none, the engine refuses naming `documents` in its own words "documents has no token in any text: the vocabulary is empty". The list itself holds one entry with an id and a text, so it is not the non-empty array message, and a call that cannot build a vocabulary does not run.'),
  ('appliedai', 'beginner', 'module', 'm03-tf-idf', 15, 'EKD-018 scores a cosine of 0.553949 against Q04. What does that figure tell you?', '["The likelihood, 0.553949, that the assessor would judge EKD-018 relevant to Q04 on the four-grade scale", "How closely its weighted words line up with the query''s, a score used only for ranking", "The share of Q04''s words that appear anywhere in the text of EKD-018", "That EKD-018 was judged grade 2, which the cosine records"]'::jsonb, 1, 'A cosine is the dot product of two unit vectors: how closely the passage''s weighted words line up with the query''s. It is a score for ranking and never a probability, so it says nothing about how likely EKD-018 is to answer Q04. It is a weighted measure and counts no plain share of words, and the judged grade is fixture data the cosine never reads.'),
  ('appliedai', 'beginner', 'module', 'm04-bm25', 1, 'System A weights each matched word by the Lucene idf. Over the five stated passages, with df 2, what weight does oil get?', '["1.693147, the smoothed idf that scikit-learn uses", "0.875469, adding 1 to (5 - 2 + 0.5) / (2 + 0.5) before the logarithm", "0.241162, the idf the six stated saturation passages give the word oil when b is set to 0", "0.707107, oil''s weight in the unit query vector"]'::jsonb, 1, 'BM25 uses the Lucene idf ln(1 + (N - df + 0.5) / (df + 0.5)); with N 5 and df 2 that is 0.875469. 1.693147 is oil''s TF-IDF idf on the same passages, a different formula. 0.241162 is oil''s idf over the six saturation passages, a different corpus, and 0.707107 is a TF-IDF query weight.'),
  ('appliedai', 'beginner', 'module', 'm04-bm25', 2, 'Why can the BM25 idf in this engine never be negative?', '["The engine drops every word that appears in more than half the passages before it scores anything.", "A negative idf is refused, naming `k1`, so the call stops before it can be returned.", "It is clipped at 0 after the Robertson form is computed.", "The Lucene form adds 1 inside the logarithm, so even a word in every passage keeps a small positive idf."]'::jsonb, 3, 'The Lucene idf is ln(1 + (N - df + 0.5) / (df + 0.5)), and the 1 inside the logarithm keeps the argument above 1, so the idf stays positive; ekene, in 44 of 60 passages, still scores 0.315385. No word is dropped for being common, no refusal is involved, and the engine does not compute the Robertson form at all.'),
  ('appliedai', 'beginner', 'module', 'm04-bm25', 3, 'For "oil rate" on the hand set, d1 scores 2.191027 by BM25. How is that score built?', '["oil and rate each contribute 1.095514, and the score is their sum", "It is the cosine 0.715911 scaled up by k1 + 1", "oil contributes 2.191027 and rate adds nothing, having been counted already", "Each word''s idf 0.875469 is multiplied by its count of 2, and the two products are then averaged"]'::jsonb, 0, 'A BM25 score is a sum over the distinct query terms found in the passage of idf x tf (k1 + 1) / (tf + k1 (1 - b + b dl / avgdl)). In d1 oil and rate each have tf 2 and contribute 1.095514, which sums to 2.191027. The cosine is TF-IDF''s score, every matched term adds its own part, and the count enters through the saturating fraction, never as a plain product.'),
  ('appliedai', 'beginner', 'module', 'm04-bm25', 4, 'oil appears twice in d1 and twice in d3, yet contributes 1.095514 to d1 and 1.024632 to d3. Why?', '["d3 also holds rates, which BM25 treats as a second copy of rate and deducts from oil", "The idf of oil is lower in d3", "d3 is longer, 12 tokens against 10, and b marks a longer passage down", "d3 ranks second, and each rank below the first loses a fixed share of every contribution it has"]'::jsonb, 2, 'With the same tf and the same idf, the only difference is length: d3 has 12 tokens and d1 has 10, against an average of 7.400000, and the length term tf + k1 (1 - b + b dl / avgdl) grows with dl. The idf belongs to the word across the corpus, rates is a different token with nothing deducted, and rank is an outcome of the score.'),
  ('appliedai', 'beginner', 'module', 'm04-bm25', 5, 'With k1 set to 0, how do d1 and d3 compare for "oil rate"?', '["0 each, since k1 = 0 switches the term weighting off entirely and every score collapses to nothing", "2.191027 and 1.722606, as k1 affects only passages longer than the average length", "The call is refused, naming `k1`, since 0 is below the accepted range for the parameter", "1.750937 each, the sum of their matched terms'' idf"]'::jsonb, 3, 'At k1 = 0 the fraction is 1 for any count, so each matched term scores its idf alone: d1 and d3 both match oil and rate and both score 1.750937, although d1 says rate twice. 2.191027 and 1.722606 are the scores at the default 1.2. 0 is accepted: the refusal is for k1 below 0, and its message says 0 scores each matched term at its idf.'),
  ('appliedai', 'beginner', 'module', 'm04-bm25', 6, 'In the saturation table (b = 0, k1 1.2), a term''s contribution divided by its idf climbs 1.000000, 1.375000, 1.571429, 1.774194, 1.941176 as tf goes 1, 2, 3, 5, 9. Where does it head?', '["Toward 9, the largest count in the table, which the ratio would reach at the next repeat", "Toward k1 + 1 = 2.2, which it never reaches", "It grows without limit, each repeat adding the same amount to the score as the one before", "Toward 1, since b = 0"]'::jsonb, 1, 'The fraction tf (k1 + 1) / (tf + k1) climbs toward k1 + 1 = 2.2 and never reaches it: each extra repeat adds less, which is saturation. The table itself shows equal repeats adding less each time, so growth is neither linear nor unbounded, and b = 0 only removes length, leaving the climb from 1.000000 in place.'),
  ('appliedai', 'beginner', 'module', 'm04-bm25', 7, 'Q13 is scored at b = 0 and at b = 1. Which passage is first at each?', '["EKD-030 (43 tokens) at b = 0, and EKD-029 (29 tokens) at b = 1", "EKD-029 at both, since b changes scores and never the order of the top of a list", "EKD-006 (56 tokens) at b = 0, as the longest passage always wins without length normalisation", "EKD-030 at both, since b alters only the fifth place and the tie at the cutoff"]'::jsonb, 0, 'At b = 0 length plays no part and the longer EKD-030 is first at 10.217811; at b = 1 the full ratio dl / avgdl applies and the shorter EKD-029 is first at 10.305812. So b does change the order. EKD-006 is fourth at b = 0, and length alone decides nothing without the matched words.'),
  ('appliedai', 'beginner', 'module', 'm04-bm25', 8, 'What does the engine return for b = 1.5?', '["Scores computed at b = 1, with a note that the value was clipped", "A refusal: \"k1 must be a finite number, 0 or more (0 scores each matched term at its idf)\"", "A refusal: \"b must be a number from 0 to 1 (0 removes length normalisation)\"", "Scores that mark long passages down harder than b = 1 does, by half again"]'::jsonb, 2, 'b must lie from 0 to 1, and a value outside is refused naming `b` in the engine''s words "b must be a number from 0 to 1 (0 removes length normalisation)". The engine never clips silently. The k1 message is the refusal for a negative k1, and no score is computed for a refused b.'),
  ('appliedai', 'beginner', 'module', 'm04-bm25', 9, 'BM25 is handed "oil oil rate" over the five stated passages. What is d1''s score?', '["More than 2.191027, as the repeated oil adds its 1.095514 a second time", "0.679173, the cosine TF-IDF gives the same query", "1.095514, since oil is doubled and rate is dropped", "2.191027, exactly the score of \"oil rate\", since a repeated query word counts once"]'::jsonb, 3, 'The engine keeps the distinct query terms, Okapi''s query-frequency factor with k3 = 0, so "oil oil rate" returns exactly the scores of "oil rate": d1 2.191027, d3 1.722606. 0.679173 is d1''s TF-IDF cosine for the repeated query, since TF-IDF does count the repeat, and no query word is dropped.'),
  ('appliedai', 'beginner', 'module', 'm04-bm25', 10, 'Q02 "initial oil rate of Ekene-3": which query term gives EKD-043 its largest contribution, and why is it so large?', '["of, at 1.537842, since of appears twice in EKD-043 and a count of 2 doubles a term", "rate, at 2.176711, since rate is in only 6 passages and has the highest idf of the query, 2.239072", "oil, since EKD-043 mentions oil three times", "initial, at 1.918143, the rarest query word"]'::jsonb, 1, 'EKD-043''s terms are rate 2.176711, of 1.537842, ekene 0.306601 and 3 1.108697; rate, in 6 passages, has the largest idf, 2.239072. of has tf 2 and gains less than double because counts saturate. EKD-043 never mentions oil or initial: 1.918143 is initial''s contribution in EKD-010.'),
  ('appliedai', 'beginner', 'module', 'm04-bm25', 11, 'On Q02, which query term has the smallest BM25 idf, and what is it?', '["ekene, in 44 of the 60 passages, at 0.315385", "of, in 19 passages, at 1.140459, since a small word is always weighted least", "oil, in 24 passages, at 0.912201, since oil is the most common word in a field''s reports", "3, which is a single character and so has an idf of 0"]'::jsonb, 0, 'The idf falls as df rises: ekene is in 44 passages and has 0.315385, the smallest, yet still above 0. of and 3 share 1.140459 at df 19, well above ekene, oil has 0.912201 at df 24, and single-character tokens are kept and weighted like any other.'),
  ('appliedai', 'beginner', 'module', 'm04-bm25', 12, 'A caller sets k1 to -0.5, hoping to reward passages that say a word once. What happens?', '["Scores at k1 = 0, with a note that negative values are raised to 0", "A refusal naming `b`, since k1 is checked together with b", "A refusal naming `k1`: \"k1 must be a finite number, 0 or more (0 scores each matched term at its idf)\"", "Scores in which each repeat lowers a passage''s score, since saturation turns downward below 0"]'::jsonb, 2, 'k1 must be 0 or more, and the engine refuses -0.5 naming `k1` in its own words "k1 must be a finite number, 0 or more (0 scores each matched term at its idf)". It never raises a value silently, the field named is k1 itself, and no score is computed for a refused k1.'),
  ('appliedai', 'beginner', 'module', 'm04-bm25', 13, 'The engine keeps (k1 + 1) in the BM25 numerator, as Robertson and Zaragoza write it; Lucene 8 and later drop it. What does dropping it do?', '["The ranking reverses, since the numerator then shrinks as a term repeats", "k1 then has no effect on the score at all, so every value of k1 gives the same scores", "Each score becomes a figure between 0 and 1", "It scales every score by the same factor and leaves the ranking order unchanged"]'::jsonb, 3, 'Dropping (k1 + 1) scales every score by the same factor and leaves the order, so a ranking from either form is the same list; only the scores differ, and a BM25 score should be compared with one computed by the same form. k1 still appears in the denominator, and no form bounds a score between 0 and 1.'),
  ('appliedai', 'beginner', 'module', 'm04-bm25', 14, 'A BM25 call is given passages made of punctuation only. What does the engine return?', '["Every passage, ranked at score 0", "A refusal: \"documents has no token in any text: BM25 needs an average document length above 0\"", "A note, \"no document contains a query term, so no document is ranked\", with an empty list and no refusal at all", "A refusal: \"documents has no token in any text: the vocabulary is empty\""]'::jsonb, 1, 'BM25 divides each length by avgdl, and with no token anywhere avgdl is 0, so the engine refuses naming `documents`: "documents has no token in any text: BM25 needs an average document length above 0". The note is for a query no passage contains in a corpus that has tokens, the vocabulary message is TF-IDF''s, and nothing is ranked at score 0.'),
  ('appliedai', 'beginner', 'module', 'm04-bm25', 15, 'Q13 is scored at k1 1.2 and at k1 2. What changes?', '["Each top 5 score falls, since a larger k1 divides each term by more", "The order reverses, with EKD-037 moving from fifth place to first place once k1 is raised to 2", "Each top 5 score rises, EKD-029 goes from 9.951737 to 10.388779, and the order holds", "Nothing, since k1 matters only when b is 0"]'::jsonb, 2, 'A larger k1 lets repeats keep counting for longer, and on Q13 each of the five top scores rises at k1 2 while the order holds: EKD-029 9.951737 to 10.388779, EKD-030 9.798866 to 10.116345, down to EKD-037 at fifth, 6.222042 to 6.469637. The claim is about the top 5 the course prints; a larger k1 does not raise every score in the corpus. k1 applies whatever b is.'),
  ('appliedai', 'beginner', 'module', 'm05-ranking-and-metrics-at-k', 1, 'Q10 "diesel spill during bunkering" is run by BM25 at k 5. How many passages does the list hold?', '["5, because the list is filled to k with the next passages at score 0", "1, since the two twins merge into one entry", "2, since only EKD-046 and EKD-058 contain a query word", "60, since k applies only to the metrics and the ranking keeps every passage"]'::jsonb, 2, 'Only a score above 0 is ranked, so a list can be shorter than k: on Q10 only 2 passages contain a query word. No passage is added at score 0, the twins stay two entries because each id is ranked once, and the cutoff applies to the list itself.'),
  ('appliedai', 'beginner', 'module', 'm05-ranking-and-metrics-at-k', 2, 'EKD-046 and EKD-058 both score 13.884966 by BM25 on Q10. Which ranks first, and by what rule?', '["EKD-046, since scores that agree to 12 significant digits tie and ties go to the id ascending", "EKD-058, since the later copy of a passage is taken to be the corrected version of it", "Either, drawn at random with a seed, so repeated runs can differ", "EKD-046, because it is longer"]'::jsonb, 0, 'The two carry the same text and score the same, so they tie and the id ascending puts EKD-046 first. The rule is stated so the same inputs always give the same list: no draw decides, no copy is treated as a correction, and identical texts have identical lengths.'),
  ('appliedai', 'beginner', 'module', 'm05-ranking-and-metrics-at-k', 3, 'Q10 is run again at k = 1. What does the engine report?', '["It keeps both twins, since a tie is never split by the cutoff, and reports a list of 2", "A refusal naming `k`, since k 1 would split a tied pair", "tieAtCutoff false, since only one passage is left in the list", "It keeps EKD-046, drops EKD-058, and reports tieAtCutoff true"]'::jsonb, 3, 'The first and second passages tie and the cut falls between them, so the id keeps EKD-046 and tieAtCutoff is true: the flag warns that a metric on that list rests on the id. k 1 is a whole number from 1 to 1000 and is accepted, and the cutoff is never stretched to hold a tie.'),
  ('appliedai', 'beginner', 'module', 'm05-ranking-and-metrics-at-k', 4, 'Passages n2 and n1 score 0.470003629246 and 0.470003616427 at 12 significant digits for "oil" with b = 1e-7. Both print 0.470004. How are they ranked?', '["n1 above n2, since they tie at 0.470004 and the id ascending decides", "n2 above n1, since the 12-digit keys differ and there is no tie", "Together, in one tied group, since scores that print alike at six decimals always tie in the engine", "n1 above n2, as the passage with more tokens wins"]'::jsonb, 1, 'Two scores tie when they agree to 12 significant digits. The keys are 0.470003629246 and 0.470003616427, which differ, so there is no tie and n2 ranks above n1 on its score; with ids alone n1 would come first. Printed alike at six decimals is not equal, and n1''s extra token lowers its score.'),
  ('appliedai', 'beginner', 'module', 'm05-ranking-and-metrics-at-k', 5, 'Why does the engine use a 12-digit key to decide ties and never a relative tolerance?', '["Every passage would tie under a tolerance, since BM25 scores differ only in the sixth decimal", "Speed: a key runs faster, and that is the only reason stated", "A key is transitive; with a tolerance, a can be near b and b near c while a is far from c, which breaks a sort", "Tolerances cannot be computed on a score above 0"]'::jsonb, 2, 'The stated reason is transitivity: two scores with the same key tie, full stop, while near-to-near chains under a tolerance break a sort. BM25 scores on the Ekene set differ in their leading digits, as Q13''s run from 9.951737 down to 6.222042 shows, speed is no stated reason, and a tolerance is computable on any score.'),
  ('appliedai', 'beginner', 'module', 'm05-ranking-and-metrics-at-k', 6, 'Which of these values of k does the engine accept?', '["1000", "0, the empty cutoff, as a way to rank without keeping anything", "2.5, rounded down to 2 before the ranking is cut", "1001"]'::jsonb, 0, 'k must be a whole number from 1 to 1000, so 1000 is accepted. 0, 2.5 and 1001 are each refused with the engine''s own words "k must be a whole number from 1 to 1000". The engine never rounds a k, and the cap of 1000 holds whatever the corpus size.'),
  ('appliedai', 'beginner', 'module', 'm05-ranking-and-metrics-at-k', 7, 'The stated ranking c, a, x, b, d is scored against the judgments a 3, b 2, c 0, d 1, e 2, at k 5 and grade 1 or more. What is the precision at 5?', '["0.750000, from 3 relevant retrieved over the 4 relevant judged", "1.000000, as every passage in the list was judged", "0.800000, from the 4 judged passages in the top 5, a, b, c and d, over 5", "0.600000, from 3 relevant in the top 5 over 5"]'::jsonb, 3, 'a, b and d are relevant at grade 1 or more, c is grade 0 and x is unjudged, which counts as grade 0: 3 relevant in the top 5, over 5, is 0.600000. 0.750000 is the recall, 3 over the 4 relevant judged. x was never judged, and a judged passage at grade 0 is still not relevant.'),
  ('appliedai', 'beginner', 'module', 'm05-ranking-and-metrics-at-k', 8, 'Which judged passage keeps the stated list''s recall at 5 below 1.000000?', '["x, which nobody judged and which counts as grade 0 in the top 5", "c, heading the list at grade 0", "e, graded 2 and missing from the list", "d, at grade 1"]'::jsonb, 2, 'Recall asks how many of the relevant judged passages made the top 5. a, b, d and e clear grade 1, and e never appears in the list, so 3 of 4 are found, 0.750000. x and c sit in the list without being relevant, which lowers precision and leaves recall alone, and d''s grade 1 counts in full at the default threshold.'),
  ('appliedai', 'beginner', 'module', 'm05-ranking-and-metrics-at-k', 9, 'In the stated ranking, what is the reciprocal rank?', '["1.000000, since c heads the list and every judged passage counts as a find", "0.500000, since the first relevant passage is a, at rank 2", "0.200000, from the last relevant passage, d, at rank 5", "0.333333, one over the rank of x"]'::jsonb, 1, 'Reciprocal rank is 1 over the rank of the first relevant passage in the top 5. c at rank 1 is grade 0, so the first relevant passage is a at rank 2 and the reciprocal rank is 1 / 2, 0.500000. A judged passage counts only at the threshold, it is the first relevant passage that counts, and x is unjudged.'),
  ('appliedai', 'beginner', 'module', 'm05-ranking-and-metrics-at-k', 10, 'System A retrieves only 2 passages for Q10, both relevant. What is its precision at 5?', '["1.000000, since both passages it ranked are relevant, 2 over the 2 ranked", "Null with a note, since the list is shorter than k", "0.500000, since one of the two is a duplicate", "0.400000, since precision at 5 divides by 5 even when fewer are ranked"]'::jsonb, 3, 'Precision at 5 is relevant in the top 5 over 5, whatever the list''s length: 2 / 5, 0.400000. That is the stated choice trec_eval makes; dividing by the passages ranked would give a list of two a perfect figure. A short list is no reason for a null, and both twins are judged relevant, so both count.'),
  ('appliedai', 'beginner', 'module', 'm05-ranking-and-metrics-at-k', 11, 'For Q02, system A''s first relevant passage is EKD-003 at rank 4. What are its hit and reciprocal rank at 5?', '["Hit 1 and reciprocal rank 0.250000", "Both 0, since three passages graded 0 come first in the list", "Hit 1 and reciprocal rank 1.000000, since a hit is the same thing as a first place", "A hit of 4 and reciprocal rank 0.250000, since hit counts the rank reached"]'::jsonb, 0, 'Hit is 1 when any relevant passage is in the top 5, and reciprocal rank is 1 / 4 for a first relevant passage at rank 4, 0.250000. Hit is generous and reciprocal rank sees the drop; hit is only ever 0 or 1, and a hit does not move the first relevant passage to rank 1.'),
  ('appliedai', 'beginner', 'module', 'm05-ranking-and-metrics-at-k', 12, 'Q14 has 3 relevant passages at grade 1 or more. What does system A score on it at 5?', '["Recall returned as null with a reason, since none of its relevant passages was found", "Hit 0, reciprocal rank 0.000000 and recall 0.000000", "Hit 1 and reciprocal rank 0.500000, from the second passage", "Precision 0.600000 and recall 1.000000"]'::jsonb, 1, 'BM25 retrieves none of Q14''s 3 relevant passages in the top 5, so hit, reciprocal rank and recall are all 0 on this planted lexical trap. Recall is null only when no passage is relevant at all, as on Q24; Q14 has 3, so its recall is a plain 0.'),
  ('appliedai', 'beginner', 'module', 'm05-ranking-and-metrics-at-k', 13, 'At k 5, relevant at grade 1 or more, system B''s MRR is 0.923913 and system A''s 0.880435. What does the difference say?', '["B beats A on every metric, so B should be chosen", "More of the relevant passages are found by B, since MRR counts every relevant find in the top 5 of each query", "System B puts its first relevant passage higher on average, while system A has the higher recall", "A trails on hit rate and on recall as well"]'::jsonb, 2, 'MRR is the mean reciprocal rank, so B''s higher figure means its first relevant passage sits higher on average. System A''s recall at 5 is 0.673188 against B''s 0.658696, and its precision 0.443478 against 0.434783, so neither system wins everywhere. MRR looks only at the first relevant passage, and A''s hit rate is lower but its recall higher.'),
  ('appliedai', 'beginner', 'module', 'm05-ranking-and-metrics-at-k', 14, 'How many of the 24 queries enter system A''s means at k 5, and why?', '["24, with Q24 scored 0 on every metric in line with the default rule", "22, since Q14 and Q24 both fail to reach a hit", "24, with Q24''s recall set to 1.000000 since there was nothing to find", "23, as Q24 has no relevant passage and is excluded and listed"]'::jsonb, 3, 'A query with no judged passage at grade 1 or more is excluded from every mean and listed, with the reason "no judged document has grade 1 or more", so 23 queries are included. Excluding and listing is the default. Q14 has relevant passages and stays in the means with its zeros, and Q24''s recall is returned as null, never filled in.'),
  ('appliedai', 'beginner', 'module', 'm05-ranking-and-metrics-at-k', 15, 'Q01 has 8 relevant passages at grade 1 or more, and system A finds 3 of them in its top 5. What is its recall at 5?', '["0.375000, and at 5 it could never pass 5 / 8", "0.600000, since 3 of the 5 retrieved passages are relevant to Q01", "1.000000, since the list is full and no more fit", "0.625000, the recall a list holding 5 relevant passages would reach"]'::jsonb, 0, 'Recall is relevant in the top 5 over relevant judged: 3 / 8, 0.375000. With 8 relevant passages and a list of 5, recall at 5 can never pass 5 / 8. 0.600000 is Q01''s precision at 5, a full list is no reason for full recall, and 5 relevant in the top 5 is not what system A found.'),
  ('appliedai', 'beginner', 'module', 'm06-answers-that-cite-sources', 1, 'What does the engine take as an answer when it checks one?', '["The short answer alone, compared with the reference answer for the query", "A text and the list of passage ids it cites", "Any text at all, checked against the whole corpus for each figure", "The ranked list of passages, read as the answer"]'::jsonb, 1, 'An answer in this course is a text and the list of passage ids it cites, and the engine checks the answer''s claims against the passages it cites. It never checks figures against the whole corpus as support, and the ranked list is what the answer is checked with, never the answer itself.'),
  ('appliedai', 'beginner', 'module', 'm06-answers-that-cite-sources', 2, 'A stated answer cites d1 and d4, with d1, d2 and d4 retrieved: Ekene-1 made 120 bopd; the survey read 2,096 psia on 2023-01-01, a "water injection" start, and 45% water, -2 skin. What is its supported fraction?', '["0.500000, 3 of 6 claims, since Ekene-1 is a claim found in d1", "0.666667, 4 of 6, as the date and the quote are found in d2, a retrieved passage", "1.000000, since every claim appears in some passage or another", "0.333333, 2 of 6 claims"]'::jsonb, 3, 'The six claims are 120, 2,096, 2023-01-01, the quote, 45 and -2. 120 is in d1 and 2,096 in d4; the date and the quote are in d2, which was retrieved and not cited, and 45 and -2 are in no passage: 2 of 6, 0.333333. Ekene-1 is an identifier and makes no claim, and support needs a passage that is both cited and retrieved.'),
  ('appliedai', 'beginner', 'module', 'm06-answers-that-cite-sources', 3, 'In that stated answer, why does "Ekene-1" make no claim?', '["A number directly after - that follows a letter is part of an identifier", "Well names are removed by the stop list before claims are read", "It does, and the claim is supported by d1, which names Ekene-1 in its text", "Only numbers above 100 are read as claims, so a well number such as 1 is too small to count"]'::jsonb, 0, 'The claim rule says a number directly after a letter, or after - _ or / that follows a letter or digit, is part of an identifier and not a claim, so the 1 in Ekene-1 makes none. The stop list plays no part in reading claims, and any number standing apart is a claim, however small, as the -2 shows.'),
  ('appliedai', 'beginner', 'module', 'm06-answers-that-cite-sources', 4, 'How does the claim reader treat "45%" in an answer?', '["A quote, since the percent sign marks it as a quoted span to be matched", "A fraction, since a percentage is divided by 100 before it is matched", "As the number 45, since a percent sign is ignored", "No claim, since a figure with a unit sign is skipped"]'::jsonb, 2, 'The basis states "a percent sign ignored", so "45%" is the number 45. Quotes are spans in double quotes, the engine does not rescale a percentage, and a figure followed by a percent sign is still a claim.'),
  ('appliedai', 'beginner', 'module', 'm06-answers-that-cite-sources', 5, 'The date 2023-01-01 in the stated answer is in d2, which was retrieved and not cited. What reason does the engine give?', '["\"the date 2023-01-01 is not in the cited passages d1 and d4; it appears in no passage of the corpus\"", "\"found in d2\"", "\"the date 2023-01-01 is not in the cited passages d1 and d4; it appears in retrieved passage d2, which the answer does not cite\"", "\"the date 2023-01-01 is not in the cited passages d1 and d4; it appears only in passage d2, neither cited nor retrieved\""]'::jsonb, 2, 'The engine''s reason names where the date is: in retrieved passage d2, which the answer does not cite. The date does appear in the corpus, so "no passage of the corpus" is wrong, a claim in an uncited passage is never "found", and d2 was retrieved, so "neither cited nor retrieved" is wrong too.'),
  ('appliedai', 'beginner', 'module', 'm06-answers-that-cite-sources', 6, 'In the stated answer the text reads "45% water, -2 skin". Why is -2 a claim with value -2?', '["Every hyphen before a digit makes a negative number, including the one inside the well name Ekene-1", "The claim reader drops signs, and 2 is what is matched", "Skin values are always negative, so the reader adds the sign", "The minus follows a space, a non-alphanumeric character, so it leads a negative number"]'::jsonb, 3, 'The basis allows a leading minus only after a non-alphanumeric character, so after a space -2 is a negative number, checked with value -2; it is in no passage. The hyphen in Ekene-1 follows a letter, so that is an identifier, the sign is kept, and the reader knows nothing of skin.'),
  ('appliedai', 'beginner', 'module', 'm06-answers-that-cite-sources', 7, 'The tokeniser splits "2,096" into 2 and 096. What does the claim reader make of it?', '["The single value 2096, since digits with comma thousands groups are one number", "Two claims, 2 and 096, checked one by one", "No claim at all, since a comma between digits makes the figure an identifier", "A decimal value, with the comma taken as a decimal point, as some reports write it"]'::jsonb, 0, 'The claim rule reads digits with optional comma thousands groups and a decimal part as one number, so "2,096" is the value 2096 and is found in d4. Retrieval and claim reading are stated separately: the tokeniser''s split serves matching words. A comma never turns a figure into an identifier or a decimal point.'),
  ('appliedai', 'beginner', 'module', 'm06-answers-that-cite-sources', 8, 'System A''s 24 answers make 49 claims, of which 47 are supported. What is its pooled supported fraction?', '["0.666667, the fraction of the Q13 answer, the answer with the most claims", "0.959184, 47 over 49", "0.500000, the Q06 answer''s fraction, taken as the lowest", "1.000000, all found"]'::jsonb, 1, 'The pooled fraction counts claims: 47 supported over 49, 0.959184. Answers with more figures weigh more. A single answer''s fraction, such as Q06''s 0.500000 or Q13''s 0.666667, says nothing about the pool, Q13 has 3 claims where Q16 and Q18 have 5, and the check fails a claim whose figure is not in the cited passages even when every citation was retrieved, as the Q06 and Q13 claims show.'),
  ('appliedai', 'beginner', 'module', 'm06-answers-that-cite-sources', 9, 'System A''s Q06 answer states 20.3, which is in EKD-007. What is the engine''s reason for it?', '["\"the number 20.3 is not in the cited passage EKD-001; it appears in retrieved passage EKD-007, which the answer does not cite\"", "\"the number 20.3 is not in the cited passage EKD-001; it appears only in passage EKD-007, neither cited nor retrieved\"", "\"found in EKD-007\"", "\"the number 20.3 is not in the cited passage EKD-001; it appears in no passage of the corpus\""]'::jsonb, 1, 'EKD-007 was neither retrieved nor cited, so the figure came from somewhere the answer cannot show, and the reason says exactly that. EKD-007 was not in system A''s retrieved list, so "retrieved passage EKD-007" is wrong; a claim is never found in an uncited passage; and 20.3 is in EKD-007, so it is in the corpus.'),
  ('appliedai', 'beginner', 'module', 'm06-answers-that-cite-sources', 10, 'System A''s Q13 answer repeats the year from "the end of 2025", and the check finds 2025 in EKD-037, which was retrieved and not cited. What kind of slip is it?', '["A figure from outside what the system saw, as in the Q06 answer", "A date claim, since 2025 is read as a year", "No slip, since a year repeated from the query is never read as a claim", "A figure from a passage the system saw and did not cite, planted in the fixture"]'::jsonb, 3, 'The reason says "it appears in retrieved passage EKD-037, which the answer does not cite": the system saw that passage and failed to cite it. The Q06 slip is the other kind, a figure from a passage neither retrieved nor cited. A date claim needs the full YYYY-MM-DD form, so 2025 alone is a number, and the reader takes it as a claim like any other.'),
  ('appliedai', 'beginner', 'module', 'm06-answers-that-cite-sources', 11, 'System A''s answers to Q14 and Q24 state no number, date or quote. How are they treated?', '["Their supported fraction is returned as null, with the reason, and they add nothing to the pooled fraction", "They are refused, naming `text`, since an answer must hold at least one claim before the check will run on it", "Each scores 1.000000, as an answer with no claim has nothing unsupported and counts as fully supported in the pool", "Each scores 0, pulling the pooled fraction down"]'::jsonb, 0, 'The fraction is undefined for an answer with no claim, and the engine returns it as null with the note "the answer has no checkable claim (no quote, date or number), so the supported fraction is undefined". The call is not refused, the fraction is never filled in as 1 or 0, and the pooled figure counts only claims.'),
  ('appliedai', 'beginner', 'module', 'm06-answers-that-cite-sources', 12, 'An answer cites one id that is no passage of the corpus and one passage that was not retrieved for its query. How are the two citations treated?', '["Both are dropped silently, and the claims are then checked against every passage the system retrieved", "The unknown id is refused, naming `citations`, and the call stops", "The unknown id is flagged unknown; the other is flagged notRetrieved and supports nothing", "Both support claims as usual, since a citation is taken at its word"]'::jsonb, 2, 'The citations basis is exact: a citation that is not a passage of the corpus is flagged unknown, and one that was not retrieved for the query is flagged notRetrieved and supports nothing. Flags are reported, never dropped, an unknown id is flagged without a refusal, and an unretrieved citation supports no claim.'),
  ('appliedai', 'beginner', 'module', 'm06-answers-that-cite-sources', 13, 'System A''s Q01 answer has 2 claims, both found in its cited, retrieved passage EKD-018. What does "supported" tell you about that answer?', '["The answer is right, since the passage was retrieved and cited and the figures were found in it word for word", "The check read EKD-018''s judged grade for Q01 and counted each figure as supported because that grade is 3", "No other passage in the corpus contains a figure that contradicts it, since the check searches them all", "Both figures appear in EKD-018; whether the answer is true is a question the check does not decide"]'::jsonb, 3, 'In this course grounded is supported by a cited and retrieved passage, a statement about the passage and never about the truth of the answer; the check does not decide whether the answer is true or whether the passage is about the right well. The claim check never reads a judged grade, so no grade makes a figure supported, and the engine looks for no contradicting passage.'),
  ('appliedai', 'beginner', 'module', 'm06-answers-that-cite-sources', 14, 'In what order does the claim reader pick claims out of an answer?', '["Quoted spans first, then ISO dates, then numbers", "Numbers first, then dates, then quotes, so each figure is claimed as early as possible", "Left to right as the words appear, each one read as a quote, a date or a number", "Dates first, then the rest"]'::jsonb, 0, 'The basis states quoted spans first, then ISO dates YYYY-MM-DD, then numbers. The order is by kind, whatever the position in the text, so numbers are taken last; neither a left-to-right reading nor dates first is the stated rule.'),
  ('appliedai', 'beginner', 'module', 'm06-answers-that-cite-sources', 15, 'A quoted span in an answer, such as "water injection", is checked against a passage. What must match?', '["The exact characters, capital letters and punctuation included", "The same run of tokens, so case and punctuation do not matter and the words must appear together and in order", "Each word of the quote anywhere in the passage, in any order and with any gap between them, as separate tokens", "The first word alone, as the quote''s key"]'::jsonb, 1, 'A quote is supported as the same run of tokens under the tokeniser''s rule, so case and punctuation fall away while the words must appear together and in the same order. An exact character match would fail on case, words scattered anywhere would not be a run, and every word of the quote counts.'),
  ('appliedai', 'beginner', 'final', null, 1, 'With the stop list off, how large is the vocabulary of the 60 Ekene passages, and how many tokens do they carry?', '["505 distinct tokens, over 2299 tokens in all", "60 distinct tokens, one per passage, over 183 tokens", "574 distinct tokens, over 2299 tokens in all", "318 distinct tokens, the size of scikit-learn''s word list, over 574 tokens"]'::jsonb, 2, 'The corpus carries 2299 tokens, from 16 to 58 a passage with a mean of 38.316667, and 574 distinct tokens. 505 is the vocabulary with the stop list on. 183 is the count of judged (query, passage) pairs, and 318 is the length of the stop list.'),
  ('appliedai', 'beginner', 'final', null, 2, 'How many (query, passage) pairs carry a judged grade in the Ekene set?', '["183, pooled from both systems'' top 5 plus the assessor''s additions", "All of them, every one of the 60 passages judged for each of the 24 queries", "120, the top 5 of system A for each of the 24 queries", "24, one answering passage per query"]'::jsonb, 0, '183 pairs are judged. The pool took every passage in the top 5 of either system, plus passages the assessor added, and left the rest unjudged, where they count as grade 0. Judging every pair, one system alone, or only an answering passage would each give a different set, and Q24 has no answering passage at all.'),
  ('appliedai', 'beginner', 'final', null, 3, 'Who or what wrote the answer texts of systems A and B?', '["A language model at build time, whose output was then frozen into the fixture files for the course", "The engine, which drafts one answer per query from the top 5 passages each time a panel runs", "The assessor who graded the passages, as a byproduct of the judging", "They are hand-written fixture text, written once and committed"]'::jsonb, 3, 'The answer texts are hand-written fixture text: no model produced them, at build time or at run time, and they stand in for what a copilot returns. The engine writes no answer, and the judged grades are a separate fixture from the answers.'),
  ('appliedai', 'beginner', 'final', null, 4, 'Handed a copilot''s cited answer, what work does the engine actually do on it?', '["Deciding whether the answer is true by comparing it with the reference answer for the query", "Looking for the answer''s numbers, dates and quotes in the passages it cites", "Asking a second language model whether the answer reads well", "Rewriting any unsupported sentence so that it matches a passage"]'::jsonb, 1, 'The engine checks a claim by finding it in a passage: it does not decide whether an answer is true, asks no model to judge an answer, and writes no text. Its check reports each claim as supported or unsupported with a reason and leaves the answer as it was.'),
  ('appliedai', 'beginner', 'final', null, 5, 'A documents list holds a passage whose id is an empty string. What is the engine''s message?', '["documents must be a non-empty array of { id, text }", "documents[0].text must be a string", "documents[0].id must be a non-empty string", "documents[1].id repeats EKD-001 (documents[0])"]'::jsonb, 2, 'An empty id is refused on its own, naming `documents[0].id`, in the engine''s words "documents[0].id must be a non-empty string". The array message is for no documents at all, the text message for a text that is not a string, and the repeat message for an id given twice.'),
  ('appliedai', 'beginner', 'final', null, 6, '`retrieve` is given a list of queries whose first text is null. Which field does the refusal name?', '["query, the single-query field that `rankBm25` uses", "queries", "documents[0].text, the first passage in the corpus the call ranks against", "queries[0].text"]'::jsonb, 3, 'When several queries run at once each is checked by position, so a null first text is refused naming `queries[0].text`: "queries[0].text must be a string". `query` is the field of a single-query call, the list itself is accepted, and the passages are a separate input.'),
  ('appliedai', 'beginner', 'final', null, 7, 'Which Ekene query has no passage judged above grade 0?', '["Q24, \"subsea tree replacement on Ekene-5\"", "Q14, \"Is Ekene-5 producing water?\", since BM25 retrieves none of its passages", "Q10, \"diesel spill during bunkering\", since only 2 passages match it", "Q02, \"initial oil rate of Ekene-3\", whose top passage is graded 0"]'::jsonb, 0, 'Q24 has no passage judged above 0 and an empty reference: nothing in the corpus answers it. Q14 has 3 relevant passages that BM25 misses, Q10 has 2 relevant passages, both retrieved, and Q02 has 5 relevant passages although its first-ranked passage is graded 0.'),
  ('appliedai', 'beginner', 'final', null, 8, 'With the stop list switched on, which token leaves `Average reservoir pressure 2,096 psia on 2023-01-01.`?', '["reservoir, the only common word in the sentence", "on, taking the count from 10 to 9", "psia, since unit abbreviations are on scikit-learn''s list", "none, since a sentence of figures and units has no stop words at all"]'::jsonb, 1, 'The sentence gives 10 tokens, average reservoir pressure 2 096 psia on 2023 01 01, and the stop list removes 1: on. reservoir and psia carry meaning and stay, and the sentence does hold a stop word.'),
  ('appliedai', 'beginner', 'final', null, 9, '`Monthly H2S drill: 0 ppm H2S.` is tokenised. What comes out?', '["monthly h 2 s drill 0 ppm h 2 s, 10 tokens, since digits break a word apart", "only monthly drill ppm, since the single character 0 and the codes are dropped as noise", "four tokens, monthly h2s drill ppm, with the repeat and the 0 removed", "monthly h2s drill 0 ppm h2s, 6 tokens"]'::jsonb, 3, 'Letters and digits that sit together stay together, so H2S is the one token h2s, and it appears twice; the 0 is a single character and is kept. The text gives 6 tokens. Nothing inside [a-z0-9] is split, nothing is dropped as noise, and repeats are kept.'),
  ('appliedai', 'beginner', 'final', null, 10, 'Where does the engine''s stop list come from, and how long is it?', '["A list written for oilfield text, 30 words long, that keeps well and top", "The 574 words of the Ekene vocabulary, marked by hand", "scikit-learn''s ENGLISH_STOP_WORDS, 318 words, BSD-3-Clause", "NLTK''s English list, which the engine applies by default to every query"]'::jsonb, 2, 'The engine exports ENGLISH_STOP_WORDS, scikit-learn''s list of 318 words under BSD-3-Clause, and leaves it off by default. It is a general English list, which is exactly why it removes well, top, bottom, fire and system, and 574 is the corpus vocabulary.'),
  ('appliedai', 'beginner', 'final', null, 11, 'A passage records the date 2023-01-01. Why does its token list carry 01 twice?', '["The date splits at its hyphens into 2023, 01 and 01", "The passage repeats a well number, and 01 is its code", "01 is the token the engine uses for any empty piece", "The stop list adds 01 as a marker each time it removes a word"]'::jsonb, 0, 'An ISO date such as 2023-01-01 becomes three tokens, 2023, 01 and 01, because the hyphens separate; a repeated token counts every time. Empty pieces are dropped, never replaced, and the stop list only removes words, and it is off here in any case.'),
  ('appliedai', 'beginner', 'final', null, 12, 'A user searches the Ekene corpus with the query "2096" for a pressure written "2,096 psia". What goes wrong?', '["Nothing, since the engine reads 2,096 and 2096 as the same number when it ranks", "The passage holds the tokens 2 and 096, so the query token 2096 matches nothing", "The query is refused, since a query made only of digits is not text", "It matches every passage with a 2 or a 0 in it"]'::jsonb, 1, 'For retrieval the comma separates, so "2,096" is indexed as 2 and 096 and the token 2096 finds nothing there. Reading 2,096 as one value is the claim reader''s job, a separate rule. A string of digits is still a string and is accepted, and matching is by whole tokens.'),
  ('appliedai', 'beginner', 'final', null, 13, 'In Q02 "initial oil rate of Ekene-3", the well number becomes the token 3. How many Ekene passages contain that token?', '["1, the well report for Ekene-3, since the token is kept tied to its well name", "0, since single-character tokens are dropped before a query is scored", "44, the same as ekene, since the two are always found together in the passages", "19, so the 3 matches passages about other wells as well"]'::jsonb, 3, 'Ekene-3 becomes ekene and 3, and single-character tokens are kept, so the 3 can match any other 3 in a passage: it is in 19 passages. The token carries no link to its well name, and ekene, in 44 passages, is counted on its own.'),
  ('appliedai', 'beginner', 'final', null, 14, 'Which of these words does scikit-learn''s stop list remove?', '["oil, since it appears in most production notes", "pressure, as a very common word in survey passages across the Ekene corpus", "fire, a word that matters in an HSE note", "psia, like other units"]'::jsonb, 2, 'fire is one of the words the list removes that carries meaning in oilfield text, together with well, top, bottom, system, no and not. oil, pressure and psia are not on it: the stated texts keep oil and rate, and pressure and psia, with the list on. The list was written for general English, and it removes common function words and a few others, never domain terms chosen for their frequency in these passages.'),
  ('appliedai', 'beginner', 'final', null, 15, 'd4 is "Pressure survey: 2,096 psia.", 5 tokens with norm 4.525864. What weight do pressure, survey, psia and 096 each carry after scaling?', '["0.200000, one fifth each, since the passage has 5 tokens", "0.463693, a large share, because the passage has few words", "2.098612, their idf, since scaling applies only to long passages", "0.374105, the weight every word of d4 carries"]'::jsonb, 1, 'Each of those four words has count 1 and idf 2.098612, and dividing by the norm 4.525864 gives 0.463693. The token 2 has the lower idf 1.693147 and ends at 0.374105. Scaling divides by the norm, so the weights are not a plain fifth, and every passage with words is scaled, short ones included.'),
  ('appliedai', 'beginner', 'final', null, 16, 'For "oil rate" on the hand set, d3 scores the cosine 0.503451. Which products sum to it?', '["oil 0.707107 x 0.474658 and rate 0.707107 x 0.237329", "d1''s products, oil 0.707107 x 0.506225 and rate 0.707107 x 0.506225", "The BM25 terms, oil 1.024632 plus rate 0.697974", "Raw counts over length: oil 1.693147 x 2 plus rate 1.693147 x 1, divided by 12"]'::jsonb, 0, 'The cosine is the dot product of the unit query and passage vectors: d3''s oil weight is 0.474658 and its rate weight 0.237329, each times 0.707107. The 0.506225 pair is d1''s row, the 1.024632 and 0.697974 pair are d3''s BM25 contributions, and the engine never divides by a token count.'),
  ('appliedai', 'beginner', 'final', null, 17, 'On the hand set, why is the df of the token 2 equal to 2?', '["It appears twice in d2, and df counts every occurrence", "The two dates in the hand set each supply one 2", "The engine assigns df 2 to every single digit", "It is in d2, from Ekene-2, and in d4, from the 2 of 2,096"]'::jsonb, 3, 'df counts passages that contain a token at least once. The 2 comes from Ekene-2 in d2 and from the comma-split 2,096 in d4: two unrelated pieces of text share a token because the engine counts strings. df ignores repeats, and there is no fixed df for digits.'),
  ('appliedai', 'beginner', 'final', null, 18, 'Why does the query "oil rate" have the unit vector oil 0.707107, rate 0.707107 on the hand set?', '["Each weight is the square root of the word''s df divided by the number of passages", "A query is always split evenly across its words, whatever their idf, so any two-word query gets these", "Each word appears once and both have idf 1.693147, so the two equal weights are scaled to length 1", "Because the two words match d1 equally"]'::jsonb, 2, 'The query is weighted the same way as a passage: count times idf, then scaled to unit length. Two equal raw weights scaled to length 1 give 0.707107 each. Unequal idfs would give unequal weights, as Q04''s query vector shows, and the query vector is built before any passage is compared.'),
  ('appliedai', 'beginner', 'final', null, 19, 'What does `rankTfidf` return besides the top k by cosine?', '["Nothing else, the ranked list of ids is the whole result", "The query vector, the terms dropped as outside the vocabulary, and each term''s two weights", "A probability of relevance for every ranked passage", "Each passage''s BM25 score, for comparison"]'::jsonb, 1, 'The function table lists the query vector, the dropped terms and the top k by cosine with each term''s query and passage weight, so the working can be printed. A cosine is a score for ranking and never a probability, and BM25 is a separate function.'),
  ('appliedai', 'beginner', 'final', null, 20, 'Q04 ranked by TF-IDF puts EKD-057 fifth at 0.251461. What was it judged?', '["Grade 0, judged not relevant to Q04", "Grade 3, the passage that answers Q04", "Unjudged, since a fifth-place passage is left out of the pool", "Grade 1, related"]'::jsonb, 0, 'The Q04 list runs EKD-018 (grade 2), EKD-010 (3), EKD-011 (2), EKD-020 (1) and EKD-057 (0). The answering passage is EKD-010, second, and every passage in either system''s top 5 was pooled and judged, fifth place included.'),
  ('appliedai', 'beginner', 'final', null, 21, 'Sublinear tf is switched on for TF-IDF. What does it change?', '["Each idf becomes its logarithm, so rare words count for less than before", "Every passage vector is scaled to the length of its token count", "BM25''s k1 is set to 0", "Each count c becomes 1 + ln c before the idf, so repeats in a passage count for less"]'::jsonb, 3, 'Sublinear tf replaces a raw count c by 1 + ln c before the idf is applied, which damps repeated words. The idf formula is untouched, the unit-length scaling is unchanged, and the switch belongs to TF-IDF alone; BM25''s saturation is set by its own k1.'),
  ('appliedai', 'beginner', 'final', null, 22, 'Why is avgdl 7.400000 on the hand set, when d1 to d4 hold 10, 10, 12 and 5 tokens?', '["Only the passages that match the query count, and d4 is skipped", "avgdl is fixed by the engine at a default for any small corpus", "The empty d5 counts in the mean with length 0, so the total is divided by 5", "The lengths are counted with the stop list on"]'::jsonb, 2, 'avgdl is the mean token count over all 5 passages, and d5 counts in the mean with length 0. Every passage counts whether or not it matches, avgdl is computed from the corpus, and the stop list is off, so the lengths are the full token counts.'),
  ('appliedai', 'beginner', 'final', null, 23, 'What happens to BM25''s length term for a passage of exactly average length?', '["The passage is marked down by b, since average length is the threshold for a penalty", "dl / avgdl is 1, so the bracket 1 - b + b dl / avgdl is 1 whatever b is", "Its score is 0", "It is marked up by k1"]'::jsonb, 1, 'With dl equal to avgdl the bracket is 1 - b + b, which is 1 for any b, so average length neither helps nor hurts. A longer passage makes the bracket bigger and its contribution smaller, a shorter one the opposite, and k1 sets saturation.'),
  ('appliedai', 'beginner', 'final', null, 24, 'At k1 1.2 with b 0, why is a passage that says oil nine times not scored nine times as high as one that says it once?', '["The contribution doubles with each doubling of tf, as in TF-IDF on raw counts", "The later repeats add more, since the idf is applied again at each repeat of the word", "Length normalisation, since b is 0", "Each extra repeat adds less, so a word said many times is not rewarded in proportion"]'::jsonb, 3, 'The ratio climbs toward k1 + 1 = 2.2 with diminishing steps: one extra mention lifts the ratio from 1.000000 to 1.375000, while four more lift it only from 1.774194 to 1.941176. That is saturation. It does not double, the idf is applied once per term, and b = 0 removes length from the score.'),
  ('appliedai', 'beginner', 'final', null, 25, 'Q13 at b 0 has EKD-006 (56 tokens) fourth and EKD-002 (58 tokens) fifth. Where are they at the default b 0.75?', '["Out of the top 5, once length counts", "Still fourth and fifth, since b changes scores and leaves membership alone", "First and second, since longer passages gain from length normalisation", "Tied at the cutoff with EKD-027"]'::jsonb, 0, 'At b 0 length plays no part and the long passages EKD-006 and EKD-002 hold places 4 and 5; at b 0.75 the top 5 is EKD-029, EKD-030, EKD-028, EKD-027 and EKD-037, so both drop out. Length normalisation marks long passages down, and the tie at the cutoff belongs to the b 0 list.'),
  ('appliedai', 'beginner', 'final', null, 26, 'Why does EKD-003, the passage that answers Q02, score only 4.084216 and rank fourth by BM25?', '["Its grade 3 is subtracted from its score to keep the ranking blind", "It mentions oil only once", "It has neither rate nor initial, and at 56 tokens it is the longest of the five", "Its idf for oil is lower than every other passage''s"]'::jsonb, 2, 'EKD-003 matches oil, of, ekene and 3 but not the two heaviest query words, rate and initial, and its 56 tokens mark every contribution down. BM25 never reads the grades, EKD-003 has oil twice, and an idf belongs to the word across the corpus, the same for every passage.'),
  ('appliedai', 'beginner', 'final', null, 27, 'What does "a repeated query word counts once" correspond to in the Okapi BM25 family?', '["The Lucene idf with the 1 added inside the logarithm", "The query-frequency factor with k3 = 0, treating the query as a set of words", "Setting b to 0, which removes the passage length from the score entirely, whatever the query", "k1 = 0, at which each repeat in the passage scores its idf alone"]'::jsonb, 1, 'Okapi''s k3 weights a query word by how often the query repeats it; the engine keeps the distinct query terms, which is k3 = 0, and says so in its basis. The Lucene idf, b and k1 act on the passage side, on rarity, length and repeats in the passage.'),
  ('appliedai', 'beginner', 'final', null, 28, 'On the hand set, d3 holds rate once. What does rate contribute to d3''s BM25 score for "oil rate"?', '["0.875469, its idf, since tf 1 always contributes exactly the idf", "1.095514", "0.506225, the rate weight TF-IDF gives the word", "0.697974"]'::jsonb, 3, 'd3''s row reads oil: 2, 1.024632; rate: 1, 0.697974. At tf 1 the fraction (k1 + 1) / (1 + k1 (1 - b + b dl / avgdl)) equals 1 only when that bracket is 1, and d3 is longer than average, so rate contributes less than its idf. 1.095514 is rate in d1 with tf 2, and 0.506225 is a TF-IDF weight in d1.'),
  ('appliedai', 'beginner', 'final', null, 29, 'Q02''s query word of says nothing about the question. Why does it still earn EKD-043 a contribution of 1.537842?', '["It is in only 19 of the 60 passages, so its idf is 1.140459, and EKD-043 uses it twice", "BM25 gives every word the same weight", "of is on the stop list, and stop words are weighted up when the list is off", "EKD-043 is graded 3 for Q02"]'::jsonb, 0, 'BM25 matches words and knows nothing of meaning: of is in 19 passages and has idf 1.140459, a sizeable weight, and EKD-043''s "rate of penetration" uses it twice. Weights differ by idf, the stop list is off and adds no weight, and EKD-043 is graded 0.'),
  ('appliedai', 'beginner', 'final', null, 30, 'Q06 is ranked by BM25 at k 5. What does the engine report about ties?', '["No ties, since only duplicate texts can share a score", "Four passages tie, EKD-001, EKD-003, EKD-005 and EKD-006, and tieAtCutoff is true", "A tie between EKD-046 and EKD-058, the duplicated spill note", "Two passages tie, and the engine keeps both by stretching the list to 6"]'::jsonb, 1, 'Q06 by BM25 at k 5 ties [["EKD-001","EKD-003","EKD-005","EKD-006"]] and tieAtCutoff is true. Different texts can tie, the spill-note twins belong to Q10, and a list is never stretched: the id ascending decides and the flag reports it.'),
  ('appliedai', 'beginner', 'final', null, 31, 'Across the 24 queries at k 5, where does each method report a tie at the cutoff?', '["Nowhere, since k 5 is wide enough to hold every tie", "BM25 on Q10 alone, from the twin spill notes", "TF-IDF on every query, since cosines are rounded", "BM25 on Q01, Q06, Q17 and Q22, TF-IDF on Q22"]'::jsonb, 3, 'The engine reports a tie at the cutoff on Q01, Q06, Q17 and Q22 by BM25 and on Q22 by TF-IDF. The Q10 twins tie at ranks 1 and 2 of a list of 2, so the cut does not fall between them at k 5, and cosines are compared by the 12-digit key, never rounded to six decimals.'),
  ('appliedai', 'beginner', 'final', null, 32, 'By TF-IDF, EKD-046 and EKD-058 both score 0.464024 on Q10. How are they ordered?', '["EKD-046 first, by the id ascending, with the two reported as tied", "EKD-058 first, since TF-IDF breaks ties by the newer passage", "In input order, since the tie rule applies to BM25 only and cosines keep the order given", "Only one is kept, since duplicate texts are merged"]'::jsonb, 0, 'The ranking rule is the same for both methods: equal 12-digit keys tie and the id ascending decides, so EKD-046 comes first and the engine reports [["EKD-046","EKD-058"]]. No method prefers a newer passage, input order is never used, and each id is ranked once.'),
  ('appliedai', 'beginner', 'final', null, 33, 'At k 5, relevant at grade 1 or more, what are the two systems'' mean precisions over the included queries?', '["A at 0.673188, B at 0.658696", "0.880435 for A, 0.923913 for B", "System A 0.443478, system B 0.434783", "B 1.000000 and A 0.956522"]'::jsonb, 2, 'Mean precision at 5 is 0.443478 for system A and 0.434783 for system B. 0.673188 and 0.658696 are the mean recalls, 0.880435 and 0.923913 the MRRs, and 0.956522 and 1.000000 the hit rates, each over the 23 included queries.'),
  ('appliedai', 'beginner', 'final', null, 34, 'System B''s hit rate at 5 is 1.000000 and system A''s 0.956522. What accounts for A''s shortfall?', '["A retrieves fewer than 5 passages on several queries", "A misses every relevant passage on Q14, the lexical trap, so one included query scores hit 0", "Q24 is counted for A and excluded for B", "A''s list for Q10 holds only 2 passages"]'::jsonb, 1, 'Hit rate is the mean hit over the 23 included queries, and system A scores hit 0 only on Q14, where BM25 retrieves none of the 3 relevant passages. Q24 is excluded for both systems by the same rule, and Q10''s short list still holds both relevant passages, so its hit is 1.'),
  ('appliedai', 'beginner', 'final', null, 35, 'Every one of Q04''s 4 relevant passages lands in system A''s top 5. Which pair is right for that query?', '["Recall 0.800000 with precision 1.000000", "Both 1.000000, since every relevant passage was found", "0.800000 for each of the two", "Precision 0.800000, recall 1.000000"]'::jsonb, 3, 'Precision is 4 relevant in the top 5 over 5, 0.800000, and recall is 4 found over 4 relevant judged, 1.000000. Swapping them confuses the denominators: precision divides by k and recall by the relevant judged, and finding every relevant passage fills recall while the fifth place holds a passage below the threshold, which keeps precision below 1.'),
  ('appliedai', 'beginner', 'final', null, 36, 'System A on Q15: the top relevant passage sits second, and 2 of the 3 relevant passages make the list. Which pair gives its reciprocal rank and recall?', '["0.500000 and 0.666667", "1.000000 and 0.666667", "0.500000 and 0.400000, the precision", "0.333333 and 0.500000"]'::jsonb, 0, 'Reciprocal rank is 1 / 2 for a first relevant passage at rank 2, and recall is 2 found over 3 relevant judged, 0.666667. 0.400000 is Q15''s precision, 2 over 5, and a first relevant rank of 2 cannot give a reciprocal rank of 1.000000.'),
  ('appliedai', 'beginner', 'final', null, 37, 'In the stated ranking c, a, x, b, d, how many unjudged passages were retrieved, and how is it graded?', '["0, since every retrieved passage is judged by pooling", "2, x and e, both unjudged", "1, the passage x, which counts as grade 0", "1, the passage x, which is dropped from the list before scoring"]'::jsonb, 2, 'x is the one retrieved passage that nobody judged, and unjudged documents count as grade 0. e was judged grade 2 and not retrieved, so it is neither unjudged nor in the list, and the engine drops no passage from a ranking before it scores it.'),
  ('appliedai', 'beginner', 'final', null, 38, 'What does every mean in this tier state beside its value so that it can be reproduced?', '["Only the method, since the cutoff and threshold are fixed by the engine", "Its cutoff, its relevance threshold and the queries left out, such as Q24", "The number of passages in the corpus, and nothing else", "The date the queries were run"]'::jsonb, 1, 'A retrieval metric is quoted with its cutoff and threshold, and a mean with the queries excluded and why: for example MRR at 5, relevant at grade 1 or more, 23 of 24 queries, Q24 excluded. k and relevantGrade are settings with defaults the caller can change, and the result depends on them.'),
  ('appliedai', 'beginner', 'final', null, 39, 'Of system A''s 22 answers that make at least one claim, how many are fully supported?', '["22, since every cited passage was retrieved", "24, counting the two answers with no claim as fully supported", "47, one for every supported claim in the whole answer set", "20, with Q06 and Q13 each carrying one unsupported claim"]'::jsonb, 3, '20 of the 22 answers with a claim are fully supported; the Q06 answer has 20.3 and the Q13 answer has 2025 unsupported. A citation being retrieved does not make every figure found, Q14 and Q24 have no claim and a null fraction, and 47 counts claims.'),
  ('appliedai', 'beginner', 'final', null, 40, 'The stated hand-set answer cites d1 and d4. For which of its claims does the engine''s reason say the figure appears in no passage of the corpus?', '["45 and -2", "The date 2023-01-01 and the quote \"water injection\"", "120 and 2,096, the two figures it was given", "Only 45"]'::jsonb, 0, '45 and -2 are in none of the five hand-set passages, so each reason ends "it appears in no passage of the corpus". The date and the quote are in d2, retrieved and not cited, and their reasons name d2; 120 and 2,096 are supported in d1 and d4. The minus in -2 follows a space, so it is a negative number and a claim.'),
  ('appliedai', 'beginner', 'final', null, 41, 'System A''s Q10 answer cites both EKD-046 and EKD-058. How does the check fare on it?', '["It is flagged, since citing two copies of one note is refused", "Its 2 claims are both supported, a fraction of 1.000000", "Each claim counts twice, once per copy, giving 4 claims", "One citation is flagged notRetrieved, since only one copy can be retrieved"]'::jsonb, 1, 'The Q10 answer makes 2 claims and both are found, so its supported fraction is 1.000000 with no flags. Citing both copies is allowed, a claim counts once however many passages hold it, and both twins were in system A''s retrieved list.'),
  ('appliedai', 'beginner', 'final', null, 42, 'An answer states the same figure twice. How many claims does the check count?', '["One, since repeated figures are merged before checking", "None, since a repeat marks the figure as a quote", "Two, since every occurrence is a claim", "Two only when the figures cite different passages"]'::jsonb, 2, 'The claim basis ends "every occurrence is a claim", so a figure stated twice is checked twice and counts twice in the fraction. Figures are never merged, quotes are spans in double quotes, and the count does not depend on citations.');
